# I need to track the current year and associate Total rows with the right year
import re

def extract_year_totals(content):
    table_match = re.search(r'<table>(.*)</table>', content, re.DOTALL)
    if not table_match:
        return {}

    table = table_match.group(1)
    rows = re.findall(r'<tr>(.*?)</tr>', table, re.DOTALL)

    year_totals = {}
    current_year = None

    for row in rows:
        cols = re.findall(r'<td[^>]*>(.*?)</td>', row, re.DOTALL)
        if len(cols) >= 3:
            first_col = cols[0].strip()

            # Check if it's a year
            if first_col.isdigit() and len(first_col) == 4:
                current_year = first_col
            # Check if it's a Total row
            elif 'Total' in first_col:
                # The total is in the 3rd column (index 2)
                total_str = cols[2].replace(',', '').strip()
                if total_str.isdigit() and current_year:
                    year_totals[current_year] = int(total_str)

    return year_totals

# Process each report
for year in [1972, 1973, 1974, 1975, 1976]:
    filename = f'/app/resources/treasury_bulletin_{year}_03_page_{45 if year == 1972 else 49 if year == 1973 else 38 if year == 1974 else 36 if year == 1975 else 38}.txt'
    with open(filename, 'r') as f:
        content = f.read()

    totals = extract_year_totals(content)
    print(f"\n{year} Report - Year Totals:")
    # Only print relevant years (1972-1978 to cover all needed)
    for y in sorted(totals.keys()):
        if 1970 <= int(y) <= 1980:
            print(f"  {y}: {totals[y]:,}")
EOF
